 using Microsoft.AspNetCore.Mvc;
 using Microsoft.Extensions.ML;
 using Microsoft.ML;
 using Microsoft.ML.Data;
 using TicketClassifier.Models;

 namespace TicketClassifier.Controllers;

 [ApiController]
 [Route("api/[controller]")]
 public class TicketController : ControllerBase
 {
     private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
     private readonly string[] _labelNames;

     public TicketController(PredictionEnginePool<TicketInput, TicketPrediction> predictionPool)
     {
         _predictionPool = predictionPool;

         // Extract label names from the model's output schema
         var engine = predictionPool.GetPredictionEngine();
         var scoreColumn = engine.OutputSchema.GetColumnOrNull("Score");
         if (scoreColumn.HasValue)
         {
             var slotNames = new VBuffer<ReadOnlyMemory<char>>();
             scoreColumn.Value.GetSlotNames(ref slotNames);
             _labelNames = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
         }
         else
         {
             _labelNames = ["Billing", "General", "Technical"];
         }
     }

     [HttpPost("classify")]
     public ActionResult<TicketClassificationResult> Classify([FromBody] TicketRequest request)
     {
         var input = new TicketInput
         {
             Subject = request.Subject,
             Description = request.Description,
             Priority = request.Priority
         };

         var prediction = _predictionPool.Predict(input);

         var scores = new Dictionary<string, float>();
         for (int i = 0; i < _labelNames.Length && i < prediction.Score.Length; i++)
         {
             scores[_labelNames[i]] = prediction.Score[i];
         }

         return Ok(new TicketClassificationResult
         {
             PredictedCategory = prediction.PredictedCategory,
             Confidence = prediction.Score.Max(),
             Scores = scores
         });
     }
 }

 public class TicketRequest
 {
     public string Subject { get; set; } = string.Empty;
     public string Description { get; set; } = string.Empty;
     public float Priority { get; set; }
 }

 public class TicketClassificationResult
 {
     public string PredictedCategory { get; set; } = string.Empty;
     public float Confidence { get; set; }
     public Dictionary<string, float> Scores { get; set; } = new();
 }

